import (
	"log"
	"sync"
	"time"
)

// Cache records when each key was last touched.
type Cache struct {
	mu   sync.Mutex
	seen map[string]time.Time
}

func warmCache(keys []string, c *Cache) {
	start := time.Now()
	for _, k := range keys {
		c.Touch(k)
	}
	log.Printf("cache warmed in %s", time.Since(start))
}

func (c *Cache) Touch(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.seen[key] = time.Now()
}

// Age reports how long ago the key was touched.
func (c *Cache) Age(key string) (time.Duration, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	at, ok := c.seen[key]
	if !ok {
		return 0, false
	}
	return time.Since(at), true
}

