// Summary holds the per-file line counts for one run.
type Summary struct {
	Files map[string]int
	Total int
}

func countLines(path string) (int, error) {
	f, err := os.Open(path)
	if err != nil {
		return 0, err
	}
	n := 0
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		n++
	}
	return n, sc.Err()
}

func isBlank(s string) bool {
	return strings.TrimSpace(s) == ""
}

func (s *Summary) Add(name string, n int) {
	if s.Files == nil {
		s.Files = make(map[string]int)
	}
	s.Files[name] = n
	s.Total += n
}

